/// <summary>
/// N.Freidenberger 28-07-2025
/// </summary>
/// <param name = "_whsWorkLineCycleCount">_whsWorkLineCycleCount</param>
/// <param name = "_acceptReject">_acceptReject</param>
/// <param name = "_workId">_workId</param>
public void updateWorkLineCycleCount(
    WHSWorkLineCycleCount   _whsWorkLineCycleCount,
    WHSAcceptReject         _acceptReject,
    WHSWorkId               _workId)
{
    next updateWorkLineCycleCount(_whsWorkLineCycleCount,_acceptReject,_workId);

    if (_acceptReject == WHSAcceptReject::Reject)
    {
        _whsWorkLineCycleCount.AVAupdateInventItemCycleCount();
    }
}
